100	  const refreshingRef = useRef(false);
101	  const mountedRef = useRef(true);
102	
103	  // Runs unconditionally from app boot regardless of exploreMode, per spec —
104	  // the background resolution loop keeps the library pre-populated so
105	  // explore mode is ready by the time the user opens it.
106	  const { artists, resolvedCount, total, scopeMissing, failedCount } =
107	    useLibraryArtists(token);
108	
109	  useEffect(() => {
110	    mountedRef.current = true;
111	    return () => {
112	      mountedRef.current = false;
113	    };
114	  }, []);
115	
116	  // Surfaces a stale-scope 403 (a session authorized before `user-follow-read`
117	  // was added — see the design doc's migration note) alongside the existing
118	  // transient controlMessage, without storing it in that same state. It's a
119	  // *persistent* condition (stays true until the user re-logs-in) riding on
120	  // a channel (`controlMessage`) that `runControl` unconditionally clears on
121	  // every successful play/pause/skip/select — storing the warning there
122	  // caused it to be silently wiped out by the next unrelated successful
123	  // control action. Deriving it instead means there's no state for anything
124	  // to clobber: a transient control error still wins while it's showing
125	  // (matches existing single-message-slot UI), and the scope warning simply
126	  // reappears on its own once that transient message clears, because
127	  // `scopeMissing` itself hasn't changed.
128	  const displayMessage =
129	    controlMessage ?? (scopeMissing ? SCOPE_WARNING : null);
130	
131	  // Fetch the currently-playing track and update state. Throws on API error so
132	  // callers (the poll loop and the control handlers) can apply their own
133	  // error handling. Both share this so a control action can refresh instantly.
134	  const syncNowPlaying = useCallback(async () => {
135	    const current = await fetchCurrentlyPlaying(token);
136	    if (!mountedRef.current) return;
137	
138	    if (!current) {
139	      devLog("[poll] nothing playing");
140	      setStatus("idle");
141	      return;
142	    }
143	
144	    // update track immediately; location catches up asynchronously
145	    setTrack(current);
146	    setStatus("playing");
147	    devLog(`[poll] now playing: ${current.artistName} – ${current.trackName}`);
148	
149	    if (current.artistName !== lastArtistRef.current) {
150	      lastArtistRef.current = current.artistName;
151	      devLog(`[poll] artist changed, looking up ${current.artistName}`);
152	      const loc = await lookupArtistLocation(current.artistName);
153	      if (mountedRef.current) setLocation(loc ?? UNKNOWN_LOCATION);
154	    }
155	  }, [token]);
156	
157	  // Shared TOKEN_EXPIRED refresh path, guarded so only one refresh runs at a
158	  // time even across overlapping poll/control errors.
159	  const refreshToken = useCallback(async () => {
160	    if (refreshingRef.current) return;
161	    refreshingRef.current = true;
162	    devLog("[poll] token expired, refreshing");
163	    try {
164	      await onTokenExpired();
165	    } finally {
166	      refreshingRef.current = false;
167	    }
168	  }, [onTokenExpired]);
169	
170	  useEffect(() => {
171	    let cancelled = false;
