          }}
        >
          {formatTime(displayMs)} / {formatTime(track.durationMs)}
        </div>
      </div>

      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 8,
          marginTop: 10,
        }}
      >
        <button
          type="button"
          onClick={onPlayPause}
          aria-label={track.isPlaying ? "Pause" : "Play"}
          style={iconButton}
        >
          {track.isPlaying ? <PauseIcon /> : <PlayIcon />}
        </button>
        <button
          type="button"
          onClick={onNext}
          aria-label="Next"
          style={iconButton}
        >
          <NextIcon />
        </button>
      </div>

      {controlMessage ? (
        <div
          style={{
            marginTop: 8,
            color: MUTED,
            fontSize: 12,
            textAlign: "center",
          }}
        >
          {controlMessage}
        </div>
      ) : null}
    </div>
  );
}

