257	  async function handleNext() {
258	    // Peek the queue in parallel with the skip request itself (not after —
259	    // once we skip, "next in queue" becomes stale) so knowing what's coming
260	    // costs no extra latency on top of the skip.
261	    const predicted = fetchQueue(token).catch(() => null);
262	    const ok = await runControl(() => skipToNext(token));
